const KEY='nexus-cte-demo-v1';
let state;try{state={...structuredClone(seeds),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=structuredClone(seeds)}
let page='day',detailId='d1',detailTab='overview',companyFilter='Toutes',buyerFilter='Tous',board='Vendeur',intelligenceTab='radar',folder=-1,searchTerm='',mobileOpen=false,quiz={step:0,answers:[],course:0};
const stages=['Préparation','Mise en marché','Négociation','Diligence','Clôture'];
const navs=[['day','Ma journée','grid'],['companies','Entreprises','building'],['buyers','Acheteurs','users'],['mandates','Mandats','briefcase'],['intelligence','Intelligence','spark'],['room','Salle de données','folder'],['academy','Académie','book'],['reports','Rapports','chart']];
