const company=id=>state.companies.find(x=>x.id===id)||state.companies[0];const deal=id=>state.deals.find(x=>x.id===id)||state.deals[0];const buyer=id=>state.buyers.find(x=>x.id===id)||state.buyers[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Mémoire locale pleine. Vos changements restent dans cette session.')}}
function log(title,context='Projet Boréal'){state.activities.unshift({title,context,date:'23 oct. 2026 · maintenant'});save()}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3400)}
function mark(c){return `<span class="company-mark ${c.color||''}">${esc(c.initial||c.name.slice(0,2))}</span>`}
function avatar(initial='AL',cls=''){return `<span class="avatar ${cls}">${esc(initial)}</span>`}
function progress(v){return `<div class="progress-bar" role="meter" aria-label="Avancement" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v}"><i style="width:${v}%"></i></div>`}
function sparkline(){return '<svg class="stat-spark" viewBox="0 0 90 35"><path d="M1 30 12 24 23 26 34 16 45 20 56 11 67 13 78 5 89 1" fill="none" stroke="#b3c598" stroke-width="1.5"/><path d="M1 30 12 24 23 26 34 16 45 20 56 11 67 13 78 5 89 1V35H1Z" fill="#b3c598" opacity=".07"/></svg>'}
function stat(label,value,foot,ic='trend',spark=false){return `<div class="card stat"><div class="stat-label">${label}${icon(ic)}</div><div class="stat-value mono">${value}</div><div class="stat-foot">${foot}</div>${spark?sparkline():''}</div>`}
function head(eyebrow,title,desc,actions=''){return `<div class="page-head spread"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`}
function render(){
 const title=navs.find(n=>n[0]===page)?.[1]||(page==='deal'?'Mandats':'Ma journée');
 $('#app').innerHTML=`<aside class="sidebar ${mobileOpen?'open':''}" aria-label="Navigation principale"><div class="brand"><svg viewBox="0 0 38 38" fill="none" aria-hidden="true"><path d="M3 5h10v20L3 34zm32 29H25V14L35 5zM13 5l22 29H25L3 5z" fill="currentColor"/></svg><div>nexus<small>LA FIRME CTE</small></div></div><div class="nav-label">Espace conseil</div><nav class="nav">${navs.slice(0,6).map(([id,name,ic])=>`<button class="nav-btn ${(page===id||(page==='deal'&&id==='mandates'))?'active':''}" data-nav="${id}" ${page===id?'aria-current="page"':''} title="${name}">${icon(ic)}<span>${name}</span>${id==='day'?`<span class="nav-count">${state.tasks.filter(t=>!t.done).length}</span>`:''}</button>`).join('')}</nav><div class="nav-label">Votre cabinet</div><nav class="nav">${navs.slice(6).map(([id,name,ic])=>`<button class="nav-btn ${page===id?'active':''}" data-nav="${id}" title="${name}">${icon(ic)}<span>${name}</span></button>`).join('')}<button class="nav-btn" data-action="settings" title="Paramètres">${icon('settings')}<span>Paramètres</span></button></nav><div class="sidebar-bottom"><div class="workspace-note"><div class="flex">${icon('shield')}<span>Un espace confidentiel</span></div><p>Vos dossiers, vos relations.<br>Au service de la relève.</p></div><button class="profile-btn" data-action="profile">${avatar('AL')}<div class="profile-copy"><strong>Alexandre Lambert</strong><small>Conseiller principal</small></div>${icon('chevron')}</button></div></aside><div class="shell"><header class="topbar"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Ouvrir la navigation">${icon('menu')}</button><div class="breadcrumb">La Firme CTE<span>/</span><strong>${title}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Rechercher dans Nexus">${icon('search')}<span>Rechercher</span><kbd>⌘ K</kbd></button><span class="demo-pill">Démo interactive</span><button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}${!state.notificationsRead?'<i class="notification-dot"></i>':''}</button>${avatar('AL')}</div></header><main id="main" class="main" tabindex="-1">${({day:renderDay,companies:renderCompanies,buyers:renderBuyers,mandates:renderMandates,deal:renderDeal,intelligence:renderIntelligence,room:renderRoom,academy:renderAcademy,reports:renderReports}[page]||renderDay)()}<div class="footer-note">${icon('lock')}Nexus · La Firme CTE <span>—</span> Données fictives · Démonstration locale <span>·</span> <a href="../../index.html">Tous les projets</a></div></main></div>`;
}
function navigate(p){page=p;searchTerm='';mobileOpen=false;render();window.scrollTo({top:0});$('#main')?.focus({preventScroll:true});history.replaceState(null,'','#'+p)}
function taskRow(t){return `<div class="task-row ${t.done?'completed':''}"><button class="task-check ${t.done?'done':''}" data-action="task" data-id="${t.id}" aria-label="${t.done?'Rouvrir':'Terminer'} : ${esc(t.title)}">${t.done?icon('check'):''}</button><div class="task-copy"><button class="text-link" style="color:inherit;text-align:left" data-action="${t.buyer?'buyer':'deal'}" data-id="${t.buyer||t.deal}"><strong>${esc(t.title)}</strong></button><small>${esc(t.sub)}</small></div><span class="task-time">${esc(t.time)}</span></div>`}
function dealTable(ds){return `<div class="table-wrap"><table class="table"><thead><tr><th>Mandat</th><th>Étape</th><th>Valeur indicative</th><th>Préparation</th><th>Prochaine action</th><th></th></tr></thead><tbody>${ds.map(d=>{const c=company(d.company);return `<tr><td><div class="flex">${mark(c)}<div class="company-name">${esc(d.project)}<small>${esc(d.code)} · ${esc(c.city)}</small></div></div></td><td>${badge(d.stage,d.stage==='Diligence'?'blue':d.stage==='Clôture'?'':d.stage==='Négociation'?'amber':'gray')}</td><td class="mono">${money(d.value,true)}</td><td><div class="table-progress">${progress(d.progress)}<span>${d.progress}%</span></div></td><td><span>${esc(d.next)}</span><div class="tiny muted" style="margin-top:5px">${esc(d.due)}</div></td><td><button class="icon-btn" data-action="deal" data-id="${d.id}" aria-label="Ouvrir ${esc(d.project)}">${icon('chevron')}</button></td></tr>`}).join('')}</tbody></table></div>`}
function renderDay(){return `${head('Vendredi 23 octobre 2026','Une belle journée pour avancer.','Bonjour Alexandre, voici ce qui mérite votre attention.',btn('Nouveau dossier','newDeal','','secondary','plus'))}<div class="stat-row">${stat('Mandats actifs',state.deals.length,'<strong>2 dossiers</strong> proches de la clôture','briefcase',true)}${stat('Acquéreurs vérifiés',state.buyers.filter(b=>b.verified).length,'Sur '+state.buyers.length+' profils dans votre réseau','users',true)}${stat('Priorités du jour',state.tasks.filter(t=>!t.done).length,'À votre rythme, une action à la fois','target')}</div><div class="dashboard-grid"><div class="stack"><section class="card focus-card"><div class="eyebrow">Votre prochain pas</div><h2>Le bon acquéreur change tout.</h2><p>Trois profils répondent aux critères du projet Boréal.<br>Votre sélection est prête à être révisée.</p>${btn('Réviser les correspondances','matches','d1','light','arrow')}<div class="focus-art"><svg viewBox="0 0 140 160" aria-hidden="true"><circle cx="74" cy="80" r="55" fill="none" stroke="#91b18a" opacity=".3"/><circle cx="74" cy="80" r="36" fill="none" stroke="#91b18a" opacity=".35"/><path d="M74 80 105 33M74 80 24 61M74 80 100 126" stroke="#b9d294" stroke-dasharray="3 4"/><circle cx="74" cy="80" r="19" fill="#d9e7b9"/><path d="m66 80 5 5 11-11" stroke="#32543d" stroke-width="2" fill="none"/><circle cx="105" cy="33" r="13" fill="#527959"/><circle cx="24" cy="61" r="10" fill="#87a575"/><circle cx="100" cy="126" r="13" fill="#b1c88d"/><circle cx="128" cy="89" r="4" fill="#95b377"/><circle cx="42" cy="124" r="3" fill="#95b377"/></svg></div></section><section class="card card-pad"><div class="card-heading"><h2>À faire aujourd’hui <span class="muted tiny">/ ${state.tasks.filter(t=>!t.done).length}</span></h2><button class="text-link" data-action="newTask">${icon('plus')}Ajouter une tâche</button></div><div class="task-list">${state.tasks.slice(0,5).map(taskRow).join('')}</div></section></div><section class="card card-pad"><div class="card-heading"><h2>Votre agenda</h2><button class="icon-btn" data-action="meeting" aria-label="Planifier une rencontre">${icon('plus')}</button></div><div class="calendar-strip">${['LUN','MAR','MER','JEU','VEN','SAM','DIM'].map((d,i)=>`<div class="day-block ${i===4?'active':''}">${d}<b>${19+i}</b></div>`).join('')}</div><div class="agenda-item"><div class="agenda-time">09 h 30</div><div class="agenda-content"><strong>Point d’équipe</strong><small>Les dossiers de la semaine · 30 min</small><div class="avatars">${avatar('AL')}${avatar('ML','blue')}${avatar('JL','rose')}</div></div></div><div class="agenda-item"><div class="agenda-time">11 h 00</div><div class="agenda-content blue"><strong>Rencontre · Groupe Novalis</strong><small>Qualification acheteur · 45 min</small><div class="avatars">${avatar('AL')}${avatar('ÉF','gold')}</div></div></div><div class="agenda-item"><div class="agenda-time">14 h 00</div><div class="agenda-content gold"><strong>Projet Méridien</strong><small>Revue financière avec Marie · 60 min</small><div class="avatars">${avatar('AL')}${avatar('ML','blue')}</div></div></div>${state.meetings.map(m=>`<div class="agenda-item"><div class="agenda-time">${esc(m.time)}</div><div class="agenda-content"><strong>${esc(m.title)}</strong><small>${esc(m.date)} · Démo</small></div></div>`).join('')}<button class="btn secondary full-width" data-action="meeting">${icon('calendar')}Planifier une rencontre</button><div class="insight-small">${icon('spark')}<div><strong>Une relation à entretenir</strong><p>Le profil de Groupe Horizon Est a besoin d’être actualisé.</p><button class="text-link" data-action="buyer" data-id="b5">Voir le profil ${icon('arrow')}</button></div></div></section></div><section class="card table-card"><div class="card-heading"><h2>Vos mandats en mouvement</h2><button class="text-link" data-nav="mandates">Tous les mandats ${icon('arrow')}</button></div>${dealTable([state.deals[0],state.deals[1],state.deals[4]])}</section>`}
function renderCompanies(){const filtered=state.companies.filter(c=>(companyFilter==='Toutes'||c.sector===companyFilter)&&[c.name,c.city,c.contact,c.sector].join(' ').toLowerCase().includes(searchTerm.toLowerCase()));return `${head('Votre registre partagé','Les bonnes relations commencent ici.','Des entreprises, des personnes et une histoire qui s’enrichit.',btn('Exporter','exportCompanies','','secondary','download')+btn('Ajouter une entreprise','newCompany','','primary','plus'))}<div class="toolbar"><div class="filters">${['Toutes','Fabrication','Distribution','Transport','Services'].map(x=>`<button class="filter-btn ${companyFilter===x?'active':''}" data-action="companyFilter" data-id="${x}">${x}${x==='Toutes'?' · '+state.companies.length:''}</button>`).join('')}</div><div class="search-input">${icon('search')}<input id="company-search" aria-label="Rechercher une entreprise" placeholder="Entreprise, ville, contact…" value="${esc(searchTerm)}"></div></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Entreprise</th><th>Secteur & région</th><th>Chiffre d’affaires</th><th>Contact</th><th>Qualification</th><th></th></tr></thead><tbody>${filtered.map(c=>`<tr><td><div class="flex">${mark(c)}<div class="company-name">${esc(c.name)}<small>${c.age} ans d’activité · ${esc(c.employees)} employés</small></div></div></td><td>${esc(c.sector)}<div class="tiny muted" style="margin-top:5px">${esc(c.city)}</div></td><td>${money(c.revenue,true)}</td><td>${esc(c.contact)}<div class="tiny muted" style="margin-top:5px">${esc(c.permission)}</div></td><td>${badge(c.status,c.status==='À qualifier'?'amber':'')}</td><td><button class="icon-btn" data-action="company" data-id="${c.id}" aria-label="Ouvrir ${esc(c.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${!filtered.length?empty('Aucune entreprise trouvée','Essayez un autre nom ou un autre secteur.'):`<div class="room-footer"><span>${filtered.length} entreprises · Sources fictives documentées</span><span>Dernière actualisation · 23 oct. 2026</span></div>`}</div><div class="callout mt"><div class="flex">${icon('shield')}<div><h3>La provenance fait partie de chaque relation.</h3><p>Ouvrez une fiche pour consulter l’origine des données, les permissions de contact et la prochaine action.</p></div></div></div>`}
function renderBuyers(){const bs=state.buyers.filter(b=>(buyerFilter==='Tous'||(buyerFilter==='Vérifiés'?b.verified:!b.verified))&&[b.name,b.sector,b.type].join(' ').toLowerCase().includes(searchTerm.toLowerCase()));return `${head('Intelligence acheteurs','Plus qu’un carnet d’adresses.','Des intentions vérifiées. Des critères précis. De meilleurs jumelages.',btn('Jumeler un mandat','matches','d1','secondary','network')+btn('Qualifier un acheteur','newBuyer','','primary','plus'))}<div class="stat-row">${stat('Profils dans votre réseau',state.buyers.length,'Une base partagée à l’échelle du cabinet','users')}${stat('Financement documenté',state.buyers.filter(b=>b.financed).length,'Capacité confirmée dans les données de démo','shield')}${stat('À actualiser',state.buyers.filter(b=>!b.verified).length,'Des préférences qui évoluent avec le temps','refresh')}</div><div class="toolbar"><div class="filters">${['Tous','Vérifiés','À actualiser'].map(x=>`<button class="filter-btn ${buyerFilter===x?'active':''}" data-action="buyerFilter" data-id="${x}">${x}</button>`).join('')}</div><div class="search-input">${icon('search')}<input id="buyer-search" aria-label="Rechercher un acheteur" placeholder="Nom, type, secteur…" value="${esc(searchTerm)}"></div></div><div class="record-grid">${bs.map(b=>`<article class="card buyer-card"><div class="spread">${mark(b)}${badge(b.verified?'Vérifié':'À actualiser',b.verified?'':'amber',b.verified?'checkcircle':'clock')}</div><h3>${esc(b.name)}</h3><div class="type">${esc(b.type)} · ${esc(b.city)}</div><p class="buyer-thesis">${esc(b.thesis)}</p><div class="buyer-metrics"><div><small>BAIIA recherché</small><strong>${money(b.min,true)} – ${money(b.max,true)}</strong></div><div><small>Capitaux propres</small><strong>${esc(b.equity)}</strong></div></div><div class="buyer-footer"><small>Vérifié le ${esc(b.date)}</small><button class="text-link" data-action="buyer" data-id="${b.id}">Voir le profil ${icon('arrow')}</button></div></article>`).join('')}</div>${!bs.length?empty('Aucun profil trouvé','Modifiez vos critères de recherche.') : ''}`}
function renderMandates(){const boards={Vendeur:stages,Acheteur:['Qualifié','Recherche active','Cible présentée','Sous LI','Conclu'],Prospection:['À contacter','Contact établi','Audit planifié','En préparation','Prêt à mandater']};const alternate=board==='Acheteur'?[{...state.deals[0],id:'b1',project:'Recherche Novalis',code:'ACH-008',stage:'Recherche active',value:6000000,sub:'Fabrication · Québec',next:'Réviser 4 cibles',due:'26 oct.',owner:'AL'},{...state.deals[1],id:'b2',project:'Recherche Saint-Laurent',code:'ACH-006',stage:'Cible présentée',value:8000000,sub:'Services · Québec',next:'Recueillir les commentaires',due:'27 oct.',owner:'ML'}]:state.companies.filter(c=>c.status==='À qualifier').map((c,i)=>({id:c.id,project:c.name,code:'PRO-0'+(14+i),stage:i?'À contacter':'Audit planifié',value:c.revenue,sub:c.sector,next:i?'Vérifier le contact':'Préparer la rencontre',due:'27 oct.',owner:'JL'}));const ds=board==='Vendeur'?state.deals:alternate;return `${head('Votre tour de contrôle','Chaque dossier, un prochain pas.','Une vue claire du chemin parcouru et de ce qui reste à accomplir.',btn('Vue client','clientPortal','d1','secondary','eye')+btn('Nouveau mandat','newDeal','','primary','plus'))}<div class="toolbar"><div class="segmented">${['Vendeur','Acheteur','Prospection'].map(x=>`<button class="${board===x?'active':''}" data-action="board" data-id="${x}">${x==='Prospection'?x:'Mandats '+x.toLowerCase()}</button>`).join('')}</div><span class="muted tiny">${ds.length} dossiers · ${board==='Vendeur'?money(ds.reduce((s,d)=>s+d.value,0),true)+' de valeur indicative':'Vue de démonstration'}</span></div><div class="kanban">${boards[board].map(stage=>`<section class="kanban-col"><div class="kanban-title"><span>${stage}</span><span class="kanban-count">${ds.filter(d=>d.stage===stage).length}</span></div>${ds.filter(d=>d.stage===stage).map(d=>`<button class="deal-card" data-action="${board==='Vendeur'?'deal':board==='Acheteur'?'buyer':'company'}" data-id="${d.id}"><div class="deal-code">${esc(d.code)}</div><h3>${esc(d.project)}</h3><div class="sector">${esc(d.sub)}</div><div class="deal-value">${money(d.value,true)}</div><div class="deal-next">${icon('clock')}${esc(d.next)}</div><div class="card-person">${avatar(d.owner)}<span class="tiny muted">${esc(d.due)}</span></div></button>`).join('')}${!ds.some(d=>d.stage===stage)?'<div class="tiny muted" style="text-align:center;padding:28px 7px;line-height:1.7">Les prochains dossiers<br>apparaîtront ici.</div>':''}</section>`).join('')}</div><div class="callout"><div class="flex">${icon('network')}<div><h3>Une transaction, plusieurs parties.</h3><p>Le projet Boréal relie la cession de l’entreprise, l’achat de l’immeuble et un bail à long terme.</p></div><div style="margin-left:auto">${btn('Voir le montage','structure','d1','secondary','arrow')}</div></div></div>`}
function finance(d){const c=company(d.company);return state.financials[d.id]||{ebitda:c.ebitda,multiple:4.5,debt:380000,cash:120000,owner:false,rent:false}}
function financialValues(f){const normalized=Number(f.ebitda)+(f.owner?45000:0)+(f.rent?18000:0);return {normalized,low:normalized*(Number(f.multiple)-.5),base:normalized*Number(f.multiple),high:normalized*(Number(f.multiple)+.5),equity:normalized*Number(f.multiple)-Number(f.debt)+Number(f.cash)}}
function validFinancialInputs(f){return ['ebitda','debt','cash'].every(key=>Number.isFinite(f[key])&&f[key]>=0&&f[key]<=1000000000)&&Number.isFinite(f.multiple)&&f.multiple>=1&&f.multiple<=20&&Object.values(financialValues(f)).every(Number.isFinite)}
function renderDeal(){const d=deal(detailId),c=company(d.company);return `<button class="back-btn" data-nav="mandates">${icon('back')}Tous les mandats</button>${head(d.code+' · '+c.sector,d.project,c.name+' · '+c.city+' · Conseiller : Alexandre Lambert',btn('Vue client','clientPortal',d.id,'secondary','eye')+btn('Changer d’étape','stage',d.id,'primary','arrow'))}<div class="spread"><div class="flex">${badge(d.stage,'','briefcase')}${badge('Accès interne','gray','lock')}<span class="tiny muted">${d.days} jours dans cette étape</span></div><button class="text-link" data-action="source" data-id="mandate">${icon('link')}Mandat signé · 1 oct. 2026</button></div><div class="tabs" role="tablist" aria-label="Sections du mandat">${[['overview','Vue d’ensemble'],['finances','Financiers & évaluation'],['buyers','Acquéreurs'],['documents','Documents'],['timeline','Échéancier']].map(([id,n])=>`<button role="tab" aria-selected="${detailTab===id}" class="tab ${detailTab===id?'active':''}" data-action="detailTab" data-id="${id}">${n}</button>`).join('')}</div>${detailTab==='overview'?dealOverview(d,c):detailTab==='finances'?dealFinance(d):detailTab==='buyers'?dealBuyers(d):detailTab==='documents'?roomFiles(d):dealTimeline(d)}`}
function dealOverview(d,c){return `<div class="detail-grid"><div><section class="card detail-hero"><div class="eyebrow">L’histoire derrière les chiffres</div><h2>Une entreprise solide.<br>Un nouveau chapitre à écrire.</h2><p>${esc(c.description)}</p><div class="tag-list"><span class="tag">Relève entrepreneuriale</span><span class="tag">${esc(c.employees)} employés</span><span class="tag">${c.age} ans d’activité</span></div></section><div class="mini-grid">${[['Chiffre d’affaires',money(c.revenue,true)],['BAIIA déclaré',money(c.ebitda,true)],['Valeur indicative',money(d.value,true)]].map(([l,v])=>`<div class="card mini-stat"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><section class="card card-pad"><div class="card-heading"><h2>Préparation du dossier</h2><span class="badge">${d.progress}% complété</span></div>${progress(d.progress)}<div style="margin-top:14px">${[['États financiers reçus et réconciliés',true],['Mandat de vente signé',true],['Sommaire aveugle révisé',true],['Liste d’acquéreurs à approuver',false],['Validation du bail et du volet immobilier',false]].map(([x,done])=>`<div class="check-row ${done?'':'warning'}">${icon(done?'checkcircle':'clock')}<span>${x}</span><button class="text-link" data-action="${x.includes('acquéreurs')?'matches':x.includes('bail')?'structure':'source'}" data-id="${x.includes('acquéreurs')||x.includes('bail')?d.id:'preparation'}">${done?'Source':'Réviser'} ${icon('chevron')}</button></div>`).join('')}</div></section><section class="card card-pad mt"><div class="card-heading"><h2>Activité récente</h2><button class="text-link" data-action="addNote" data-id="${d.id}">${icon('plus')}Ajouter une note</button></div><div class="timeline">${[...state.activities.filter(a=>a.context===d.project).slice(0,3),{title:'Sommaire aveugle révisé par Marie Leduc',date:'22 oct. 2026 · 15 h 42'},{title:'Première sélection d’acquéreurs préparée',date:'21 oct. 2026 · 10 h 15'},{title:'États financiers 2025 approuvés',date:'20 oct. 2026 · 14 h 30'}].slice(0,5).map(a=>`<div class="timeline-item">${esc(a.title)}<small>${a.date}</small></div>`).join('')}</div></section></div><div class="stack"><section class="card card-pad"><div class="eyebrow">Prochaine action</div><h2 style="margin:15px 0;font-size:20px;line-height:1.4">${esc(d.next)}</h2><div class="flex muted tiny">${icon('calendar')}Échéance : ${esc(d.due)}</div><div style="margin-top:20px">${btn('Mettre à jour','nextAction',d.id,'secondary','edit')}</div></section><section class="card card-pad"><div class="card-heading"><h2>L’équipe du dossier</h2></div><div class="team-members">${[['AL','Alexandre Lambert','Conseiller responsable',''],['ML','Marie Leduc','Analyste financière','blue'],['JL','Julie Lapierre','Coordination & diligence','rose']].map(([i,n,r,cl])=>`<div class="person">${avatar(i,cl)}<div><strong>${n}</strong><small>${r}</small></div></div>`).join('')}</div></section><section class="card card-pad"><div class="card-heading"><h2>Cadre du mandat</h2></div><dl class="definition-list"><dt>Type</dt><dd>Vente d’actions</dd><dt>Exclusivité</dt><dd>1 oct. 2027</dd><dt>Continuité de l’équipe</dt><dd>Priorité du cédant</dd><dt>Transition souhaitée</dt><dd>6 à 12 mois</dd><dt>Volet immobilier</dt><dd>Analyse distincte</dd></dl><button class="text-link mt" data-action="structure" data-id="${d.id}">Voir le montage ${icon('arrow')}</button></section><div class="callout"><h3>Le regard du cédant</h3><p>Un portail clair pour suivre les étapes, transmettre les pièces et préparer la suite.</p>${btn('Aperçu du portail','clientPortal',d.id,'secondary','eye')}</div></div></div>`}
function dealFinance(d){const f=finance(d),v=financialValues(f);return `<section class="card card-pad"><div class="card-heading"><div><h2>Une valeur qui s’explique.</h2><p class="muted tiny" style="margin-top:7px">Scénario de démonstration · Exercice 2025 · CAD</p></div>${btn('Exporter le scénario','exportFinance',d.id,'secondary','download')}</div><div class="data-note">Les hypothèses ci-dessous sont fictives et modifiables. Ce scénario illustre le fonctionnement du calcul, sans constituer une évaluation professionnelle.</div><div class="financial-inputs">${[['ebitda','BAIIA déclaré ($)',f.ebitda,'1000'],['multiple','Multiple indicatif',f.multiple,'.1'],['debt','Dette financière ($)',f.debt,'1000'],['cash','Encaisse excédentaire ($)',f.cash,'1000']].map(([id,label,val,step])=>`<div class="field"><label for="fin-${id}">${label}</label><input id="fin-${id}" data-finance="${id}" type="number" min="${id==='multiple'?'1':'0'}" max="${id==='multiple'?'20':'1000000000'}" step="${step}" value="${val}"></div>`).join('')}</div><div id="finance-results">${financeResults(f)}</div></section><div class="detail-grid mt"><section class="card card-pad"><div class="card-heading"><h2>Retraitements proposés</h2>${badge('Révision humaine','gray')}</div><p class="tiny muted" style="margin-bottom:10px">Activez un ajustement pour l’inclure dans le scénario local.</p><label class="adjustment"><input type="checkbox" data-finance="owner" ${f.owner?'checked':''}><span>Rémunération du dirigeant<small>Écart au coût de remplacement · Hypothèse illustrative</small></span><b>+45 000 $</b></label><label class="adjustment"><input type="checkbox" data-finance="rent" ${f.rent?'checked':''}><span>Normalisation du loyer<small>Loyer entre apparentés · À confirmer par un professionnel</small></span><b>+18 000 $</b></label><div class="spread mt"><span class="tiny muted">Chaque ajustement conserve sa justification.</span><button class="text-link" data-action="source" data-id="financial">Voir la source ${icon('arrow')}</button></div></section><section class="card card-pad"><div class="card-heading"><h2>Passer de la valeur aux capitaux propres</h2></div><div id="equity-bridge">${equityBridge(f)}</div><div class="data-note mt">La valeur de l’immeuble est traitée séparément. Aucun gain fiscal ni ajustement de fonds de roulement n’est présumé.</div></section></div>`}
function financeResults(f){const v=financialValues(f);return `<div class="financial-result"><div class="result-card"><small>Scénario prudent · ${(f.multiple-.5).toFixed(1)}×</small><strong>${money(v.low,true)}</strong><p>Valeur d’entreprise</p></div><div class="result-card main-result"><small>Scénario central · ${Number(f.multiple).toFixed(1)}×</small><strong>${money(v.base,true)}</strong><p>BAIIA ajusté : ${money(v.normalized,true)}</p></div><div class="result-card"><small>Scénario haut · ${(Number(f.multiple)+.5).toFixed(1)}×</small><strong>${money(v.high,true)}</strong><p>Valeur d’entreprise</p></div></div><h3 style="margin-top:26px;font-size:12px">Sensibilité · BAIIA × multiple</h3><table class="sensitivity"><thead><tr><th>BAIIA / Multiple</th>${[-1,-.5,0,.5,1].map(n=>`<th>${(Number(f.multiple)+n).toFixed(1)}×</th>`).join('')}</tr></thead><tbody>${[-.1,0,.1].map(p=>`<tr><th>${money(v.normalized*(1+p),true)}</th>${[-1,-.5,0,.5,1].map(n=>`<td class="${p===0&&n===0?'selected':''}">${money(v.normalized*(1+p)*(Number(f.multiple)+n),true)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function equityBridge(f){const v=financialValues(f);return `<dl class="definition-list"><dt>Valeur d’entreprise</dt><dd>${money(v.base)}</dd><dt>Dette financière</dt><dd>− ${money(f.debt)}</dd><dt>Encaisse excédentaire</dt><dd>+ ${money(f.cash)}</dd></dl><div class="spread" style="border-top:1px solid var(--line);margin-top:20px;padding-top:20px"><span class="tiny muted">Valeur indicative des actions</span><strong style="font-size:20px;font-weight:500">${money(v.equity,true)}</strong></div>`}
function rankedBuyers(d){const c=company(d.company);return state.buyers.filter(b=>b.type!=='Investisseur immobilier').map(b=>{let score=(b.sector===c.sector?30:b.type==='Acheteur financier'?20:10)+(c.ebitda>=b.min&&c.ebitda<=b.max?25:8)+(b.city===c.city||['Québec','Lévis'].includes(b.city)?15:7)+(b.financed?10:3)+(b.verified?10:0)+10;return {...b,matchScore:Math.min(score,98)}}).sort((a,b)=>b.matchScore-a.matchScore)}
function dealBuyers(d){const bs=rankedBuyers(d).slice(0,4);return `<div class="spread mb"><div><h2>La compatibilité, en toute transparence.</h2><p class="tiny muted" style="margin-top:8px">${bs.length} profils à considérer · Critères calculés à partir des données de démo</p></div>${btn('Exporter la sélection','exportShortlist',d.id,'secondary','download')}</div>${bs.map(b=>`<article class="card match-card"><div class="match-score">${b.matchScore}</div><div><h3>${esc(b.name)}</h3><p>${esc(b.type)} · ${esc(b.city)}</p><div class="tag-list"><span class="tag">${b.sector===company(d.company).sector?'Secteur aligné':'Secteur à confirmer'}</span><span class="tag">${b.financed?'Financement documenté':'Financement à confirmer'}</span>${b.nda?'<span class="tag">NDA enregistré</span>':'<span class="tag">NDA requis avant divulgation</span>'}</div></div><div class="match-controls">${btn('Comprendre','matchDetails',b.id,'secondary')}${btn(state.shortlist.includes(b.id)?'Sélectionné':'Sélectionner','shortlist',b.id,state.shortlist.includes(b.id)?'light':'primary',state.shortlist.includes(b.id)?'check':'plus')}</div></article>`).join('')}<div class="callout mt"><h3>Une correspondance n’est pas une autorisation de divulguer.</h3><p>La sélection reste interne. Le sommaire aveugle, le NDA et les droits de partage sont révisés avant toute communication.</p>${btn('Préparer un sommaire aveugle','teaser',d.id,'secondary','file')}</div>`}
function dealTimeline(d){const timeline=[['1 oct.','Mandat signé','Mandat et accord du cédant conservés.','checkcircle'],['8 oct.','Collecte & préparation','États financiers et questionnaire reçus.','checkcircle'],['20 oct.','Mise en marché','Sommaire aveugle et sélection à approuver.','clock'],['6 nov.','Rencontres acquéreurs','Sous réserve des autorisations de divulgation.','users'],['20 nov.','Fenêtre de lettres d’intention','Date de planification, non un engagement.','file'],['Déc.','Diligence & financement','Conditions à lever avec les professionnels.','shield'],['À confirmer','Clôture','Échéance conditionnelle au dossier.','flag']];return `<div class="detail-grid"><section class="card card-pad"><div class="card-heading"><h2>Un calendrier partagé, des attentes claires.</h2>${btn('Exporter','exportTimeline',d.id,'secondary','download')}</div><div class="timeline" style="margin-top:28px">${timeline.map(([date,title,desc,ic])=>`<div class="timeline-item"><div class="spread"><strong style="font-weight:550">${title}</strong>${badge(date,'gray')}</div><p class="activity-note">${desc}</p></div>`).join('')}</div></section><section class="card card-pad"><div class="card-heading"><h2>Conditions à suivre</h2></div>${[['Approbation du financement','Marie Leduc','26 oct.'],['Confirmation du bail','Julie Lapierre','2 nov.'],['Révision des documents','Alexandre Lambert','30 oct.']].map(([title,owner,date])=>`<div class="check-row warning">${icon('clock')}<span>${title}<small class="muted" style="display:block;font-size:10px;margin-top:5px">${owner} · ${date}</small></span></div>`).join('')}<div class="callout mt"><h3>La prochaine étape se prépare ensemble.</h3><p>Les conditions de financement et de bail restent indépendantes et visibles.</p>${btn('Voir le montage','structure',d.id,'secondary','network')}</div></section></div>`}
function renderIntelligence(){const remaining=[0,1,2].filter(x=>!state.dismissedSignals.includes(x));return `${head('Une vue d’avance','L’intelligence au service des relations.','Des signaux expliqués, des hypothèses à vérifier et des connexions utiles.',btn('Préparer un brief','copilot','','primary','spark'))}<div class="tabs"><button class="tab ${intelligenceTab==='radar'?'active':''}" data-action="intelTab" data-id="radar">Radar de succession</button><button class="tab ${intelligenceTab==='graph'?'active':''}" data-action="intelTab" data-id="graph">Réseau relationnel</button><button class="tab ${intelligenceTab==='discovery'?'active':''}" data-action="intelTab" data-id="discovery">Découverte d’acquéreurs</button></div>${intelligenceTab==='radar'?`<div class="detail-grid"><div>${[{title:'Un projet de relève se précise',company:'Atelier Boréal',text:'Le propriétaire a mentionné une transition dans les 18 à 24 mois lors du dernier entretien.',date:'16 oct. · Déclaration du cédant',ic:'flag',id:'c1'},{title:'Une recommandation à explorer',company:'Services Altitude',text:'Un partenaire CPA a demandé une première rencontre au sujet d’un projet de succession.',date:'20 oct. · Référence partenaire',ic:'users',id:'c4'},{title:'Des critères acheteurs à rafraîchir',company:'Groupe Horizon Est',text:'Le financement et l’échéancier n’ont pas été confirmés depuis plus de 60 jours.',date:'12 août · Profil acheteur',ic:'refresh',id:'b5'}].map((s,i)=>state.dismissedSignals.includes(i)?'':`<article class="card signal-card"><span class="signal-icon">${icon(s.ic)}</span><div class="signal-card-content"><div class="spread"><h3>${esc(s.title)}</h3>${badge(i===2?'À actualiser':'À vérifier',i===2?'amber':'gray')}</div><p>${s.text}</p><div class="tiny muted">${s.company} · ${esc(s.date)}</div><div class="flex" style="margin-top:15px"><button class="text-link" data-action="${i===2?'buyer':'company'}" data-id="${s.id}">Ouvrir la fiche ${icon('arrow')}</button><button class="text-link" data-action="dismissSignal" data-id="${i}" style="margin-left:auto;color:#9ca58d">Classer</button></div></div></article>`).join('')}${!remaining.length?empty('Votre radar est à jour','Les trois signaux de démonstration ont été examinés.') : ''}</div><div class="stack"><section class="card card-pad"><div class="card-heading"><h2>Votre territoire</h2>${badge('2 régions','gray')}</div><svg viewBox="0 0 300 190" width="100%" aria-label="Illustration du territoire de Québec et de Chaudière-Appalaches"><path d="M10 145 48 118 70 78 105 65 133 28 178 15 207 44 246 48 285 27 291 71 263 100 238 149 197 175 146 167 106 185 67 161 33 172Z" fill="#eef2e5" stroke="#d5dfc7"/><path d="m10 122 63 1 39-26 35 8 53-34 44 4 47-23" fill="none" stroke="#bdd1d3" stroke-width="11"/><path d="m10 122 63 1 39-26 35 8 53-34 44 4 47-23" fill="none" stroke="#dce8e7" stroke-width="7"/><circle cx="165" cy="86" r="7" fill="#6d8d52" stroke="white" stroke-width="3"/><circle cx="177" cy="104" r="6" fill="#afc18c" stroke="white" stroke-width="3"/><circle cx="126" cy="145" r="5" fill="#afc18c" stroke="white" stroke-width="3"/><text x="175" y="77" font-size="10" fill="#7a8c69">Québec</text><text x="187" y="109" font-size="10" fill="#8c9b7d">Lévis</text><text x="136" y="151" font-size="9" fill="#98a58c">Sainte-Marie</text></svg><p class="tiny muted">Capitale-Nationale · Chaudière-Appalaches</p></section><div class="callout"><h3>Un signal ouvre une conversation.</h3><p>Il ne prouve ni une intention de vendre ni une capacité d’achat. Chaque information conserve sa source et sa date.</p></div></div></div>`:intelligenceTab==='graph'?`<section class="card card-pad"><div class="card-heading"><h2>Le réseau du projet Boréal</h2><span class="tiny muted">Cliquez sur un acquéreur pour ouvrir sa fiche</span></div>${networkGraph()}<div class="flex" style="justify-content:center;font-size:10px;color:#9daa8d;gap:25px"><span>● Entreprise</span><span style="color:#779d94">● Acquéreur</span><span style="color:#b5a077">● Partenaire</span></div></section><div class="detail-grid mt"><div class="callout"><h3>Un chemin de confiance</h3><p>La relation avec le cabinet comptable pourrait faciliter une présentation à Groupe Novalis. Cette piste reste à confirmer avec les personnes concernées.</p>${btn('Préparer la prise de contact','copilot','','secondary','spark')}</div><section class="card card-pad"><h3>Relations sourcées</h3><div class="check-row">${icon('link')}<span>Partenaire comptable → Atelier Boréal</span>${badge('Déclaré','gray')}</div><div class="check-row">${icon('link')}<span>Groupe Novalis → Alliance Industrielle</span>${badge('À vérifier','amber')}</div></section></div>`:`<section class="card card-pad"><div class="card-heading"><div><h2>Une recherche ciblée.</h2><p class="tiny muted" style="margin-top:8px">Explorez le réseau de démonstration à partir d’un mandat.</p></div>${badge('Recherche locale','gray')}</div><form id="discovery-form" class="flex" style="align-items:flex-end"><div class="field" style="flex:1"><label for="discovery-deal">Mandat à explorer</label><select id="discovery-deal" name="deal">${state.deals.map(d=>`<option value="${d.id}">${esc(d.project)} · ${company(d.company).sector}</option>`).join('')}</select></div><button class="btn" type="submit">${icon('search')}Trouver les correspondances</button></form><div class="callout mt"><h3>Critères explicites, résultats vérifiables.</h3><p>Le secteur, le BAIIA, la région, le financement et la fraîcheur du profil déterminent le classement. Les profils inconnus ne sont jamais inventés par le moteur.</p></div></section><div id="discovery-results" class="mt"></div>`}`}
function networkGraph(){return `<svg class="graph" viewBox="0 0 720 290" role="img" aria-label="Graphe de relations du projet Boréal"><g stroke="#d7e1cd" stroke-width="1.5" fill="none"><path d="M355 145 150 60M355 145 560 60M355 145 585 225M355 145 138 225M150 60 138 225M560 60 585 225"/><path d="M150 60 560 60" stroke-dasharray="4 5"/></g><g><circle cx="355" cy="145" r="45" fill="#244e40"/><text x="355" y="143" fill="#e2edcc" text-anchor="middle" font-size="13">Projet</text><text x="355" y="162" fill="#e2edcc" text-anchor="middle" font-size="13">Boréal</text><g class="graph-node" data-action="buyer" data-id="b1" role="button" tabindex="0" aria-label="Groupe Novalis"><circle cx="150" cy="60" r="30" fill="#e3eddb" stroke="#cddbbd"/><text x="150" y="65" fill="#608344" text-anchor="middle" font-size="14">GN</text><text x="150" y="109" fill="#7b8f6a" text-anchor="middle" font-size="11">Groupe Novalis</text></g><g class="graph-node" data-action="buyer" data-id="b3" role="button" tabindex="0" aria-label="Alliance Industrielle"><circle cx="560" cy="60" r="30" fill="#e2ede9" stroke="#ccddd5"/><text x="560" y="65" fill="#648d80" text-anchor="middle" font-size="14">AI</text><text x="560" y="109" fill="#7b8f6a" text-anchor="middle" font-size="11">Alliance Industrielle</text></g><g class="graph-node" data-action="source" data-id="relationship" role="button" tabindex="0" aria-label="Relation partenaire CPA"><circle cx="138" cy="225" r="27" fill="#f2eddd" stroke="#e4dbc1"/><text x="138" y="230" fill="#ab9866" text-anchor="middle" font-size="13">CPA</text><text x="138" y="270" fill="#9e987e" text-anchor="middle" font-size="11">Partenaire comptable</text></g><g class="graph-node" data-action="buyer" data-id="b6" role="button" tabindex="0" aria-label="Patrimoine Rivage"><circle cx="585" cy="225" r="27" fill="#e3eddb" stroke="#cddbbd"/><text x="585" y="230" fill="#608344" text-anchor="middle" font-size="13">PR</text><text x="585" y="270" fill="#7b8f6a" text-anchor="middle" font-size="11">Patrimoine Rivage</text></g></g></svg>`}
function renderRoom(){return `${head('Un espace pour avancer ensemble','Chaque document, à la bonne place.','Projet Boréal · Une salle structurée, un partage explicite.',btn('Gérer les accès','access','','secondary','shield')+btn('Ajouter un document','upload','','primary','upload'))}<div class="room-summary card"><div><h3>Projet Boréal <span class="muted tiny">/ CTE-026</span></h3><p>${state.docs.length} documents · ${state.docs.filter(d=>d.status==='Révisé').length} révisés · Accès restreint</p></div><div class="flex">${badge('NDA requis','gray','lock')}${btn('Demander une pièce','requestDocument','','secondary','plus')}</div></div><div class="room-layout"><aside class="card folder-panel" aria-label="Dossiers documentaires"><button class="folder-btn ${folder===-1?'active':''}" data-action="folder" data-id="-1">${icon('folder')}Tous les documents<span>${state.docs.length}</span></button>${folders.map((f,i)=>`<button class="folder-btn ${folder===i?'active':''}" data-action="folder" data-id="${i}">${icon('folder')}${f}<span>${state.docs.filter(d=>d.folder===i).length}</span></button>`).join('')}</aside><section>${roomFiles(deal('d1'))}</section></div>`}
function roomFiles(d){const docs=page==='room'&&folder>=0?state.docs.filter(f=>f.folder===folder):state.docs;return `<div class="card table-card"><div class="card-heading"><h2>${page==='room'&&folder>=0?folders[folder]:'Documents du dossier'}</h2>${page==='deal'?btn('Ajouter','upload','','secondary small','plus'):badge(d.code,'gray')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>État</th><th>Ajouté par</th><th></th></tr></thead><tbody>${docs.map(f=>`<tr><td><div class="file-name">${icon('file','file-icon')}<div>${esc(f.name)}<small>${esc(f.ext)} · ${esc(f.size)} · ${esc(f.date)}</small></div></div></td><td>${badge(f.status,f.status==='Révisé'?'':f.status==='À réviser'?'amber':'gray')}</td><td class="muted">${esc(f.author)}</td><td><button class="icon-btn" data-action="document" data-id="${f.id}" aria-label="Ouvrir ${esc(f.name)}">${icon('eye')}</button></td></tr>`).join('')}</tbody></table></div>${!docs.length?`<div class="doc-empty">${icon('folder')}<p style="margin:15px 0">Ce dossier est prêt à recevoir ses premières pièces.</p>${btn('Ajouter une pièce','upload','','secondary','plus')}</div>`:''}<div class="room-footer"><span>${icon('lock')} Documents de démonstration</span><button class="text-link" data-action="access">Consulter les accès ${icon('arrow')}</button></div></div>${page==='deal'?`<div class="callout mt"><h3>Un sommaire avant une divulgation.</h3><p>Préparez une présentation aveugle à partir des données approuvées du dossier.</p>${btn('Préparer le sommaire','teaser',d.id,'secondary','file')}</div>`:''}`}
const courses=[['Fondamentaux du transfert',18,18,'briefcase','S1'],['Comptabilité & états financiers',27,12,'chart','S2'],['Évaluation d’entreprise',21,7,'target','S3'],['Fiscalité de la vente',29,0,'brief','S4'],['Financement d’acquisition',33,4,'building','S5'],['Processus de transaction',42,6,'network','S6'],['Prospection & acheteurs',36,10,'users','S7'],['Conformité & éthique',21,21,'shield','S8']];
function renderAcademy(){return `${head('Le savoir qui fait la différence','Grandir avec chaque dossier.','Votre académie du transfert d’entreprise · 8 parcours, 227 leçons au catalogue.',btn('Mon parcours','learningProfile','','secondary','award'))}<section class="card academy-hero"><div><div class="eyebrow">Reprendre votre apprentissage</div><h2>Lire entre les lignes<br>du BAIIA.</h2><p>Distinguer un résultat récurrent d’un ajustement exceptionnel. 6 minutes pour mieux préparer votre prochain dossier.</p>${btn('Continuer la leçon','lesson','1','light','play')}</div><svg class="academy-art" viewBox="0 0 240 200" aria-hidden="true"><circle cx="130" cy="100" r="87" fill="none" stroke="#658260" opacity=".5"/><path d="m43 60 75 22 79-24v104l-79 24-75-22Z" fill="#91ab79"/><path d="m43 48 75 22 79-24v104l-79 24-75-22Z" fill="#e0e8c8"/><path d="m118 70 79-24v104l-79 24Z" fill="#bacd9c"/><path d="m57 74 43 13m-43 6 43 13m-43 7 31 9m44-28 49-14m-49 33 49-14m-49 33 36-10" stroke="#78935d" stroke-width="3" opacity=".5"/><circle cx="190" cy="45" r="23" fill="#dce6b7"/><path d="m180 45 7 7 13-14" stroke="#537342" stroke-width="3" fill="none"/></svg></section><div class="spread mb"><h2>Vos parcours</h2><span class="tiny muted">${78+state.completedLessons.length} leçons illustrées comme complétées · Données de démo</span></div><div class="academy-grid">${courses.map(([title,count,done,ic,code],i)=>{const total=Math.min(count,done+state.completedLessons.filter(x=>x===i).length);return `<article class="card course-card"><div class="spread"><div class="course-icon">${icon(ic)}</div><span class="file-tag">${code}</span></div><h3>${title}</h3><p>${count} leçons · ${i===0||i===7?'Parcours essentiel':'À votre rythme'}</p>${progress(total/count*100)}<div class="spread"><span>${total} / ${count} complétées</span><span>${Math.round(total/count*100)}%</span></div><button class="text-link" style="margin-top:20px" data-action="lesson" data-id="${i}">${total===count?'Revoir une leçon':'Explorer le parcours'} ${icon('arrow')}</button></article>`}).join('')}</div><div class="callout mt"><div class="flex">${icon('shield')}<div><h3>Les connaissances ouvrent des portes. Les permissions restent distinctes.</h3><p>Fondamentaux et Conformité sont les prérequis du parcours interne. Les leçons de cette démo sont des exemples pédagogiques.</p></div></div></div>`}
function renderReports(){const yr=state.reportRange==='Année';return `${head('La performance qui se mesure','Comprendre ce qui fait avancer.','Des indicateurs utiles pour votre cabinet, sans perdre de vue les personnes.',btn('Exporter le rapport','exportReport','','secondary','download'))}<div class="toolbar"><div class="segmented">${['Mois','Trimestre','Année'].map(x=>`<button class="${state.reportRange===x?'active':''}" data-action="reportRange" data-id="${x}">${x}</button>`).join('')}</div><span class="tiny muted">${yr?'Janvier – octobre 2026':state.reportRange==='Mois'?'Octobre 2026':'Août – octobre 2026'} · Jeu de données illustratif</span></div><div class="stat-row">${stat('Honoraires encaissés',yr?'386 k$':state.reportRange==='Mois'?'42 k$':'128 k$','<strong>+18 %</strong> vs période précédente','chart',true)}${stat('Temps de préparation','9,4 j','Après réception des pièces complètes','clock')}${stat('Mandats clôturés',yr?'5':state.reportRange==='Mois'?'1':'2','Des transactions, des histoires de relève','checkcircle')}</div><div class="report-grid"><section class="card card-pad"><div class="card-heading"><h2>Activité du cabinet</h2><span class="tiny muted">Honoraires encaissés · k$</span></div><div class="chart-summary"><div><strong>${yr?'386':'128'} k$</strong><span>Encaissé</span></div><div><strong>${yr?'92':'32'} k$</strong><span>Recherche acquéreurs</span></div></div><svg class="chart" viewBox="0 0 580 250" aria-label="Graphique illustratif des honoraires encaissés de mai à octobre"><g stroke="#e9eee0" stroke-dasharray="3 4"><path d="M40 30H560M40 80H560M40 130H560M40 180H560"/></g><g><text x="10" y="34">60</text><text x="10" y="84">40</text><text x="10" y="134">20</text><text x="16" y="184">0</text></g>${[55,90,69,128,108,142].map((h,i)=>`<rect x="${65+i*83}" y="${180-h}" width="36" height="${h}" rx="5" fill="${i===5?'#547441':'#bfd0a4'}"/><rect x="${65+i*83}" y="${180-h}" width="36" height="${h*.2}" rx="5" fill="${i===5?'#93af71':'#dbe6c8'}"/><text x="${83+i*83}" y="205" text-anchor="middle">${['Mai','Juin','Juil.','Août','Sept.','Oct.'][i]}</text>`).join('')}<circle cx="184" cy="237" r="3" fill="#bfd0a4"/><text x="194" y="240">Conseil & transactions</text><circle cx="355" cy="237" r="3" fill="#dbe6c8"/><text x="365" y="240">Recherche acquéreurs</text></svg></section><section class="card card-pad"><div class="card-heading"><h2>Du premier échange au mandat</h2></div><p class="tiny muted" style="margin-bottom:25px">Cohorte illustrative · ${yr?'Année':'Trimestre'} 2026</p>${[['Échanges utiles',48,100],['Rencontres',24,70],['Audits réalisés',16,50],['Mandats signés',8,30],['Transactions',2,13]].map(([l,n,p])=>`<div class="funnel-row"><label>${l}</label><div class="funnel-bar"><span style="width:${p}%"></span></div><b>${yr?n*2:n}</b></div>`).join('')}<div class="insight-small" style="margin-top:30px">${icon('trend')}<div><strong>Préparer, puis accélérer.</strong><p>La disponibilité des états financiers reste le principal facteur de délai dans cette cohorte fictive.</p></div></div></section></div><div class="card table-card report-bottom"><div class="card-heading"><h2>Capacité de l’équipe</h2><span class="tiny muted">Semaine du 19 octobre</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Collaborateur</th><th>Mandats suivis</th><th>Charge prévue</th><th>Priorité</th></tr></thead><tbody>${[['AL','Alexandre Lambert','4','28 h','Mise en marché & clôture',70,''],['ML','Marie Leduc','3','32 h','Revue des financiers',80,'blue'],['JL','Julie Lapierre','3','24 h','Diligence & coordination',60,'rose']].map(([a,n,d,h,p,v,cl])=>`<tr><td><div class="flex">${avatar(a,cl)}${n}</div></td><td>${d}</td><td><div class="table-progress">${progress(v)}<span>${h}</span></div></td><td>${p}</td></tr>`).join('')}</tbody></table></div></div>`}
function empty(title,desc){return `<div class="card empty-state">${icon('search')}<h3>${title}</h3><p>${desc}</p></div>`}
function openModal(title,body,actions='',subtitle=''){const m=$('#modal');if(m.open)m.close();m.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<small>${esc(subtitle)}</small>`:''}</div><button class="icon-btn" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;m.showModal();const focus=m.querySelector('input:not([type="checkbox"]),select,textarea');if(focus)setTimeout(()=>focus.focus(),30)}
function closeModal(){$('#modal').close()}
function formActions(id,label='Enregistrer'){return `${btn('Annuler','close','','secondary')}<button class="btn" type="submit" form="${id}">${icon('check')}${label}</button>`}
function field(label,name,value='',type='text',attrs=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function selectField(label,name,values,value){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`}
function download(filename,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Le fichier de démonstration a été téléchargé.')}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>{let text=String(v??'');if(typeof v==='string'&&/^[=+@-]/.test(text.trimStart()))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function showCompany(id){const c=company(id);openModal(c.name,`<div class="flex mb">${mark(c)}<div><div class="tiny muted">${esc(c.sector)} · ${esc(c.city)}</div><div class="tag-list">${badge(c.status,c.status==='À qualifier'?'amber':'')}${badge(c.permission,c.permission==='À vérifier'?'amber':'gray')}</div></div></div><p>${esc(c.description)}</p><dl class="definition-list"><dt>Contact principal</dt><dd>${esc(c.contact)}</dd><dt>Chiffre d’affaires</dt><dd>${money(c.revenue)}</dd><dt>BAIIA déclaré</dt><dd>${money(c.ebitda)}</dd><dt>Équipe</dt><dd>${esc(c.employees)} personnes</dd><dt>Historique</dt><dd>${c.age} ans d’activité</dd><dt>Région</dt><dd>${esc(c.region)}</dd></dl><div class="source-details">${icon('link')} ${esc(c.source)}<br>Données fictives · Les sources sont illustratives dans cette démo.<button class="text-link" data-action="source" data-id="${c.id}">Voir la provenance ${icon('arrow')}</button></div><div class="callout mt"><h3>Prendre le temps de comprendre.</h3><p>Objectif, échéancier, relève interne et continuité de l’équipe : la prochaine conversation complète le portrait.</p></div>`,btn('Questionnaire cédant','intake',c.id,'secondary','file')+btn('Préparer un appel','call',c.id,'primary','phone'),'Fiche entreprise · Registre partagé')}
function showBuyer(id){const b=buyer(id);openModal(b.name,`<div class="spread mb"><div class="flex">${mark(b)}<div><h3>${esc(b.type)}</h3><div class="tiny muted" style="margin-top:6px">${esc(b.contact)} · ${esc(b.city)}</div></div></div>${badge(b.verified?'Vérifié':'À actualiser',b.verified?'':'amber')}</div><p>${esc(b.thesis)}</p><dl class="definition-list"><dt>Secteur déclaré</dt><dd>${esc(b.sector)}</dd><dt>BAIIA recherché</dt><dd>${money(b.min,true)} – ${money(b.max,true)}</dd><dt>Capitaux propres</dt><dd>${esc(b.equity)}</dd><dt>Financement</dt><dd>${b.financed?'Documenté · Exemple de démo':'À confirmer'}</dd><dt>NDA</dt><dd>${b.nda?'Exemple enregistré':'À obtenir avant divulgation'}</dd><dt>Dernière vérification</dt><dd>${esc(b.date)}</dd></dl><div class="callout"><h3>Critères déclarés</h3><p>La direction reste en place durant la transition. Les intentions et le financement sont à reconfirmer pour chaque opportunité.</p></div><button class="text-link mt" data-action="refusal" data-id="${b.id}">Consigner une réponse à une opportunité ${icon('arrow')}</button>`,btn('Réactualiser le profil','qualify',b.id,'secondary','refresh')+btn(state.shortlist.includes(b.id)?'Retirer de la sélection':'Ajouter à la sélection','shortlist',b.id,'primary','plus'),'Intelligence acheteurs · Profil de démonstration')}
function showQualification(id){const b=id?buyer(id):null;openModal(b?'Réactualiser le profil':'Qualifier un acquéreur',`<p>Capturez l’intention d’achat déclarée et les points restant à confirmer.</p><form id="buyer-form" data-id="${b?.id||''}" class="form-grid">${field('Nom de l’acquéreur','buyerName',b?.name||'','text','required maxlength="80"')}${field('Contact principal','buyerContact',b?.contact||'','text','required maxlength="80"')}${selectField('Type d’acquéreur','buyerType',['Acquéreur stratégique','Acheteur financier','Repreneur individuel','Consolidateur sectoriel','Investisseur immobilier'],b?.type)}${selectField('Secteur recherché','buyerSector',['Fabrication','Distribution','Transport','Services','Immobilier'],b?.sector)}${field('BAIIA minimum ($)','buyerMin',b?.min||250000,'number','min="0" step="1000" required')}${field('BAIIA maximum ($)','buyerMax',b?.max||1000000,'number','min="1000" step="1000" required')}${field('Ville','buyerCity',b?.city||'Québec','text','required maxlength="60"')}${field('Capitaux propres (fourchette)','buyerEquity',b?.equity||'500 k$ – 1 M$','text','required maxlength="60"')}<div class="field full"><label for="buyerThesis">Thèse d’acquisition</label><textarea id="buyerThesis" name="buyerThesis" maxlength="400" required>${esc(b?.thesis||'')}</textarea></div><label class="flex tiny"><input type="checkbox" name="buyerFinanced" ${b?.financed?'checked':''}>Financement documenté (démo)</label><label class="flex tiny"><input type="checkbox" name="buyerVerified" checked>Critères reconfirmés (démo)</label></form>`,formActions('buyer-form'))}
function showMatches(id){detailId=id||'d1';detailTab='buyers';closeModal();navigate('deal')}
function showMatchDetails(id){const b=buyer(id),d=deal(detailId),c=company(d.company);const dims=[['Secteur',b.sector===c.sector?30:b.type==='Acheteur financier'?20:10,30],['Taille / BAIIA',c.ebitda>=b.min&&c.ebitda<=b.max?25:8,25],['Géographie',['Québec','Lévis'].includes(b.city)||b.city===c.city?15:7,15],['Financement',b.financed?10:3,10],['Profil à jour',b.verified?10:0,10],['Structure / échéancier',10,10]];openModal('Pourquoi ce jumelage ?',`<div class="flex mb">${mark(b)}<div><h3>${esc(b.name)}</h3><div class="tiny muted" style="margin-top:6px">${esc(d.project)} · Score calculé sur les données de démo</div></div></div>${dims.map(([l,v,m])=>`<div class="bar-row"><span>${l}</span>${progress(v/m*100)}<span>${v}/${m}</span></div>`).join('')}<div class="source-details mt">${esc(b.thesis)}<br><br><strong>Source illustrative :</strong> entretien de qualification du ${esc(b.date)}. Le score ne prédit pas une acquisition.</div>`,btn('Voir le profil','buyer',b.id,'secondary','users')+btn(state.shortlist.includes(b.id)?'Retirer de la sélection':'Sélectionner','shortlist',b.id,'primary','check'))}
function showStage(id){const d=deal(id);openModal('Faire progresser le dossier',`<p>Le changement est enregistré dans l’historique local. Les documents et validations cités ici sont des exemples de démonstration.</p><form id="stage-form" data-id="${d.id}" class="stack">${selectField('Nouvelle étape','stage',stages,d.stage)}<div class="field"><label for="stageReason">Note de progression</label><textarea id="stageReason" name="reason" required maxlength="500" placeholder="Ce qui permet de passer à cette étape…"></textarea></div><div class="source-details">${icon('file')} Mandat de démonstration signé · 1 oct. 2026<br>${icon('shield')} Révision humaine et pièces requises en production</div></form>`,formActions('stage-form','Enregistrer la progression'),d.project)}
function showSource(id){const c=state.companies.find(c=>c.id===id);openModal('La source derrière l’information',`<div class="paper"><div class="eyebrow">Provenance · Exemple de démonstration</div><h3>${esc(c?c.name:id==='financial'?'Retraitement du BAIIA':id==='relationship'?'Relation déclarée':'Pièce du dossier')}</h3><p>${esc(c?c.source:id==='financial'?'États financiers 2025, page 6 · Note de l’analyste du 22 octobre 2026.':'Document de référence fictif préparé pour la démonstration.')}</p><dl class="definition-list"><dt>État</dt><dd>Exemple révisé</dd><dt>Responsable</dt><dd>Marie Leduc</dd><dt>Date de collecte</dt><dd>21 octobre 2026</dd><dt>Usage</dt><dd>Interne au cabinet</dd></dl><div class="source-details">${id==='financial'?'L’ajustement de rémunération de 45 000 $ suppose un coût de remplacement inférieur au coût déclaré. L’ajustement de loyer de 18 000 $ repose sur un scénario illustratif. Ces montants restent exclus tant qu’ils ne sont pas sélectionnés.':'Les données présentées sont entièrement fictives. Dans la plateforme, chaque champ conserve le document, la page ou l’entretien qui le justifie.'}</div></div>`,btn('Compris','close','','primary','check'))}
function showDocument(id){const f=state.docs.find(x=>x.id===id);if(!f)return;openModal(f.name,`<div class="spread mb"><span class="file-tag">${esc(f.ext)} · ${esc(f.size)} · ${folders[f.folder]}</span>${badge(f.status,f.status==='Révisé'?'':'amber')}</div><div class="paper"><div class="eyebrow">La Firme CTE · Projet Boréal</div><h3>${esc(f.name)}</h3><p>${f.local?'Ce fichier a été ajouté depuis votre appareil. Seules ses métadonnées sont conservées dans la démo ; son contenu n’a pas été téléversé.':'Aperçu de document fictif. Les renseignements ci-dessous illustrent le parcours de révision et ne proviennent pas d’un dossier réel.'}</p>${f.folder===1?'<dl class="definition-list"><dt>Exercice</dt><dd>2025</dd><dt>Chiffre d’affaires</dt><dd>4 250 000 $</dd><dt>BAIIA déclaré</dt><dd>680 000 $</dd><dt>Mission</dt><dd>Exemple de présentation</dd></dl>':'<p>Document à examiner dans le cadre de la préparation du dossier. La version, le responsable de la révision et les autorisations de partage restent liés à cette pièce.</p>'}<div class="paper-line"></div><div class="paper-line" style="width:87%"></div><div class="paper-line" style="width:62%"></div><div class="tiny muted" style="margin-top:25px">Usage interne · Démonstration · 23 octobre 2026</div></div>`,btn('Exporter la fiche','downloadDoc',f.id,'secondary','download')+btn(f.status==='Révisé'?'Marquer à réviser':'Marquer révisé','reviewDoc',f.id,'primary','check'),'Aperçu de démonstration, pas un document officiel')}
function showAccess(){openModal('Les bonnes personnes, le bon accès',`<p>Un NDA enregistré et une autorisation explicite sont distincts. Les accès ci-dessous sont uniquement simulés dans cette démonstration.</p>${state.access.map((a,i)=>`<div class="proposal"><div class="spread"><h3>${esc(buyer(a.buyer).name)}</h3>${badge(a.active?'Actif':'Révoqué',a.active?'':'gray')}</div><p>${esc(a.folders)}<br>Échéance : ${esc(a.expiry)} · NDA de démo enregistré</p>${btn(a.active?'Révoquer cet accès':'Rétablir l’accès de démo','toggleAccess',i,a.active?'secondary':'light',a.active?'lock':'check')}</div>`).join('')}<div class="data-note">Aucun fichier réel n’est partagé. Le contrôle d’accès serveur doit être développé avant un usage avec des données confidentielles.</div>`,btn('Fermer','close','','secondary'))}
function showStructure(id){const d=deal(id);openModal('Une transaction, trois parties',`<p>${esc(d.project)} · Montage P1 : entreprise et immeuble séparés, avec bail à long terme. Valeurs illustratives.</p><div class="canvas-flow"><div class="party">${icon('building')}<strong>Cédant</strong><small>${esc(company(d.company).name)}</small></div><span class="flow-arrow">${icon('arrow')}</span><div class="stack"><div class="party">${icon('briefcase')}<strong>Acquéreur opérateur</strong><small>Entreprise · ${money(d.value,true)}</small></div><div class="party">${icon('building')}<strong>Investisseur immobilier</strong><small>Immeuble · 1,2 M$</small></div></div></div><div class="check-row warning">${icon('link')}<span>Bail de 10 ans entre investisseur et opérateur</span>${badge('À valider','amber')}</div><div class="check-row warning">${icon('shield')}<span>Financement et conditions de clôture croisés</span>${badge('En revue','blue')}</div><div class="check-row">${icon('users')}<span>Responsables : conseiller, CPA, avocat et notaire</span></div><div class="data-note mt">Chaque volet conserve ses propres conditions, documents et honoraires. Aucune recommandation de structure juridique ou fiscale n’est formulée.</div>`,btn('Voir l’échéancier','openTimeline',d.id,'primary','calendar'))}
function showClientPortal(id){const d=deal(id);openModal('Votre projet, en toute clarté',`<div class="paper"><div class="eyebrow">La Firme CTE · Espace cédant · Aperçu</div><h3>Bonjour ${esc(company(d.company).contact.split(' ')[0])},</h3><p>Votre dossier avance. Retrouvez ici les étapes partagées par votre conseiller et les pièces à préparer.</p><div class="spread mb"><strong style="font-size:13px">${esc(d.project)}</strong>${badge(d.stage)}</div>${progress(d.progress)}<div style="margin-top:20px">${[['Mandat & objectifs','Complété','checkcircle'],['Collecte des documents','Complété','checkcircle'],['Présentation du dossier','En cours','clock'],['Rencontres acquéreurs','À venir','users']].map(([a,b,ic])=>`<div class="client-milestone">${icon(ic)}<span>${a}</span><small>${b}</small></div>`).join('')}</div><div class="callout mt"><h3>La prochaine pièce à préparer</h3><p>Le renouvellement de votre bail commercial permettra à notre équipe de compléter le dossier.</p></div></div>`,btn('Préparer une pièce','upload','','secondary','upload')+btn('Planifier une rencontre','meeting','','primary','calendar'),'Vue de démonstration · Les notes internes restent exclues')}
function showTeaser(id){const d=deal(id),c=company(d.company);openModal('Sommaire aveugle · Révision',`<div class="paper"><div class="eyebrow">Occasion de relève · ${esc(d.code)}</div><h3>${esc(c.sector)} spécialisée au Québec</h3><p>Une PME établie avec une équipe expérimentée et un savoir-faire reconnu dans son secteur. Le cédant souhaite assurer la continuité de l’entreprise.</p><dl class="definition-list"><dt>Région</dt><dd>${esc(c.region)}</dd><dt>Revenus</dt><dd>${money(Math.floor(c.revenue/1000000)*1000000,true)} – ${money((Math.floor(c.revenue/1000000)+1)*1000000,true)}</dd><dt>BAIIA</dt><dd>${money(Math.floor(c.ebitda/100000)*100000,true)} – ${money((Math.floor(c.ebitda/100000)+1)*100000,true)}</dd><dt>Structure envisagée</dt><dd>À discuter avec le conseiller</dd></dl><p>Aucune identité ni coordonnée du cédant n’est incluse dans cet aperçu. Tout partage réel nécessite la révision du conseiller.</p></div><div class="data-note mt">Brouillon de démonstration. L’anonymisation et le risque de réidentification nécessitent une validation humaine avant diffusion réelle.</div>`,btn('Exporter le brouillon','exportTeaser',d.id,'primary','download'))}
function showCopilot(){openModal('Un coup de main pour la suite',`<div class="flex mb">${icon('spark')}<span class="tiny muted">Copilote · Suggestions scénarisées, aucune IA connectée</span></div><p>À partir du dossier Boréal, voici deux prochaines actions proposées. Vous gardez la main sur chaque modification.</p><div class="proposal"><h3>Actualiser le financement de Groupe Horizon Est</h3><p>Le dernier échange date du 12 août. Une vérification de la capacité et du calendrier rendra le profil plus utile.</p><div class="proposal-actions">${btn('Créer une tâche','proposalTask','refreshBuyer','primary small','plus')}${btn('Voir le profil','buyer','b5','secondary small')}</div></div><div class="proposal"><h3>Préparer le sommaire aveugle du projet Boréal</h3><p>Les revenus et le BAIIA restent présentés par fourchettes. Les coordonnées de l’entreprise sont exclues.</p><div class="proposal-actions">${btn('Réviser le brouillon','teaser','d1','primary small','file')}</div></div><div class="source-details">Sources de démo : profil acheteur, états financiers 2025, entretien cédant. Aucune communication externe ne sera effectuée.</div>`,btn('Fermer','close','','secondary'))}
function showCall(id){const c=company(id);if(c.permission==='Ne plus contacter'){openModal('Contact suspendu',`<div class="callout"><h3>La demande de retrait est conservée.</h3><p>${esc(c.contact)} a demandé à ne plus être contacté. Aucun nouvel appel ne peut être préparé dans la démo.</p></div>`,btn('Fermer','close','','secondary'));return}openModal('Préparer une conversation utile',`<div class="phone-mock"><div class="flex" style="justify-content:center">${mark(c)}<div style="text-align:left"><h3>${esc(c.name)}</h3><p>${esc(c.contact)} · Appel simulé</p></div></div>${badge(c.permission,c.permission==='À vérifier'?'amber':'gray')}</div><div class="callout mt"><h3>Trois questions pour commencer</h3><p>Quel rôle aimeriez-vous conserver après le transfert ?<br>Qu’est-ce qui compte le plus pour votre équipe ?<br>Quel échéancier serait confortable pour vous ?</p></div><form id="call-form" data-id="${c.id}" class="stack mt">${selectField('Issue de la conversation','disposition',['Rencontre à planifier','Questionnaire demandé','À rappeler','Pas le bon moment','Ne plus contacter'])}<div class="field"><label for="callNotes">Notes de conversation</label><textarea id="callNotes" name="notes" maxlength="1000" required placeholder="Les éléments déclarés par le contact…"></textarea></div></form>`,formActions('call-form','Consigner la simulation'),'Aucun appel réel · Aucun enregistrement')}
function showIntake(id){const c=company(id);openModal('Votre projet de relève',`<div class="eyebrow mb">La Firme CTE · Questionnaire de démonstration</div><p>Quelques questions pour mieux préparer notre première rencontre. Les réponses sont enregistrées uniquement dans ce navigateur.</p><form id="intake-form" data-id="${c.id}" class="stack">${field('Votre nom','intakeName',c.contact,'text','required maxlength="80"')}${selectField('Votre horizon de transition','horizon',['Moins de 12 mois','12 à 24 mois','2 à 5 ans','Je souhaite explorer'])}${selectField('Votre implication après le transfert','involvement',['Transition progressive','Accompagnement à temps partiel','Retrait complet','À discuter'])}<div class="field"><label for="intakeGoals">Ce qui compte le plus pour vous</label><textarea id="intakeGoals" name="goals" placeholder="Continuité de l’équipe, marque, famille…" maxlength="500" required></textarea></div></form>`,formActions('intake-form','Enregistrer les réponses'))}
function showLesson(index){quiz={step:0,answers:[],course:Number(index)};renderLesson()}
const quizItems=[{title:'Le BAIIA déclaré et le BAIIA retraité',text:'Le BAIIA déclaré reflète les comptes de l’entreprise. Un retraitement documenté aide à distinguer les charges courantes des éléments exceptionnels. Une proposition d’ajustement doit conserver sa justification et être révisée.',question:'Un ajustement est proposé sans pièce justificative. Que faire ?',answers:['L’inclure pour augmenter la valeur','Le laisser en attente de justification','Le présenter comme un revenu récurrent'],correct:1},{title:'Une intention se confirme',text:'Un acheteur utile à votre réseau a des critères déclarés, un échéancier et une capacité à vérifier. Un refus sur un dossier ne signifie pas nécessairement un refus de toute acquisition.',question:'Un acheteur trouve une entreprise trop petite. Quel suivi est approprié ?',answers:['Supprimer définitivement le profil','Confirmer et consigner le critère pour ce dossier','Déduire une nouvelle fourchette sans le contacter'],correct:1},{title:'Le partage reste explicite',text:'Un NDA et un accès aux documents sont deux étapes distinctes. Le conseiller précise les documents autorisés, les personnes concernées et la durée du partage.',question:'Le NDA de l’acheteur est enregistré. Quelle est la prochaine étape ?',answers:['Ouvrir toute la salle de données','Vérifier et accorder un accès limité aux pièces appropriées','Envoyer tous les fichiers par défaut'],correct:1}];
function renderLesson(){const q=quizItems[quiz.step];if(!q){const correct=quiz.answers.filter((v,i)=>v===quizItems[i].correct).length;if(correct===3&&!state.completedLessons.includes(quiz.course)){state.completedLessons.push(quiz.course);save()}openModal(correct===3?'Une étape de plus dans votre parcours.':'Un point à revoir, puis à réessayer.',`<div style="text-align:center;padding:20px 0"><div class="course-icon" style="margin:0 auto 23px;width:60px;height:60px">${icon('award')}</div><h2>${correct} / 3 bonnes réponses</h2><p style="margin-top:15px">${correct===3?'La leçon de démonstration est complétée et votre progression est enregistrée.':'Prenez le temps de relire les trois notions. La progression sera validée après trois bonnes réponses.'}</p></div>`,btn('Revoir la leçon','lesson',quiz.course,'secondary','refresh')+btn('Retour à l’académie','finishLesson','','primary','check'));return}openModal(courses[quiz.course][0],`<div class="lesson-content"><div class="lesson-count">Exemple pédagogique ${quiz.step+1} / 3 · Démonstration</div>${progress(quiz.step/3*100)}<h3 style="margin-top:25px">${q.title}</h3><p>${q.text}</p><div class="source-details mb">Notion issue des principes du cahier produit Nexus. Ceci ne constitue ni une formation professionnelle complète ni une certification.</div><h3 style="font-size:13px">${q.question}</h3><div id="quiz-answers">${q.answers.map((a,i)=>`<button class="quiz-answer" data-action="quizAnswer" data-id="${i}"><span class="badge gray">${String.fromCharCode(65+i)}</span>${a}</button>`).join('')}</div></div>`,btn('Quitter','close','','secondary')+'<button class="btn" id="quiz-next" data-action="quizNext" disabled>Continuer '+icon('arrow')+'</button>')}
const actions={
 close:()=>closeModal(),menu:()=>{mobileOpen=!mobileOpen;render()},
 deal:id=>{detailId=id;detailTab='overview';closeModal();navigate('deal')},
 company:id=>showCompany(id),buyer:id=>showBuyer(id),matches:id=>showMatches(id),qualify:id=>showQualification(id),newBuyer:()=>showQualification(),matchDetails:id=>showMatchDetails(id),source:id=>showSource(id),document:id=>showDocument(id),structure:id=>showStructure(id),clientPortal:id=>showClientPortal(id),teaser:id=>showTeaser(id),copilot:()=>showCopilot(),call:id=>showCall(id),intake:id=>showIntake(id),stage:id=>showStage(id),access:()=>showAccess(),lesson:id=>showLesson(id),
 task:id=>{const t=state.tasks.find(x=>x.id===id);if(!t)return;t.done=!t.done;save();render();toast(t.done?'Une action de plus accomplie.':'La tâche a été rouverte.')},
 companyFilter:id=>{companyFilter=id;render()},buyerFilter:id=>{buyerFilter=id;render()},board:id=>{board=id;render()},detailTab:id=>{detailTab=id;render()},intelTab:id=>{intelligenceTab=id;render()},folder:id=>{folder=Number(id);render()},reportRange:id=>{state.reportRange=id;save();render()},
 shortlist:id=>{const added=!state.shortlist.includes(id);if(added)state.shortlist.push(id);else state.shortlist=state.shortlist.filter(x=>x!==id);save();if($('#modal').open)closeModal();render();toast(added?'Profil ajouté à votre sélection interne.':'Profil retiré de votre sélection.')},
 dismissSignal:id=>{state.dismissedSignals.push(Number(id));save();render();toast('Signal classé dans cette démonstration.')},
 reviewDoc:id=>{const f=state.docs.find(d=>d.id===id);f.status=f.status==='Révisé'?'À réviser':'Révisé';log('Document '+f.name+' : '+f.status);closeModal();render();toast('État de révision enregistré.')},
 toggleAccess:id=>{const a=state.access[Number(id)];a.active=!a.active;log((a.active?'Accès de démo rétabli':'Accès de démo révoqué')+' · '+buyer(a.buyer).name);showAccess();toast('Droits de démonstration mis à jour.')},
 openTimeline:id=>{detailId=id;detailTab='timeline';closeModal();navigate('deal')},
 finishLesson:()=>{closeModal();navigate('academy')},
 quizAnswer:id=>{quiz.answers[quiz.step]=Number(id);document.querySelectorAll('.quiz-answer').forEach((b,i)=>b.classList.toggle('selected',i===Number(id)));$('#quiz-next').disabled=false},
 quizNext:()=>{if(quiz.answers[quiz.step]===undefined)return;quiz.step++;renderLesson()},
 learningProfile:()=>openModal('Votre parcours d’apprentissage',`<div style="text-align:center;padding:10px 0 20px"><div class="course-icon" style="margin:0 auto 20px;width:58px;height:58px">${icon('award')}</div><h2>Conseiller en progression</h2><p style="margin-top:12px">${78+state.completedLessons.length} / 227 leçons illustrées comme complétées</p>${progress((78+state.completedLessons.length)/227*100)}</div><div class="check-row">${icon('checkcircle')}<span>Fondamentaux du transfert</span>${badge('Complété')}</div><div class="check-row">${icon('checkcircle')}<span>Conformité & éthique</span>${badge('Complété')}</div><div class="callout mt"><h3>Une certification interne, pas un permis professionnel.</h3><p>Le catalogue est représenté dans la démo. Trois exercices sont interactifs ; le parcours complet reste à produire et à réviser.</p></div>`,btn('Poursuivre','lesson','1','primary','play')),
 search:()=>{openModal('Rechercher dans Nexus',`<input id="global-search" class="search-modal" aria-label="Recherche globale" placeholder="Une entreprise, un acquéreur, un mandat…" autocomplete="off"><div id="global-results" class="search-results">${searchResults('')}</div>`,'','Entreprises · Acheteurs · Mandats');setTimeout(()=>$('#global-search')?.focus(),30)},
 notifications:()=>{state.notificationsRead=true;save();render();openModal('Ce qui a changé',`<div class="notification-item">${icon('users')}<div><h3>Une sélection prête à réviser</h3><p>Projet Boréal · 3 acquéreurs répondent aux critères.</p><button class="text-link" data-action="matches" data-id="d1">Voir les correspondances ${icon('arrow')}</button></div></div><div class="notification-item">${icon('file')}<div><h3>Le retraitement du BAIIA attend votre revue</h3><p>Marie Leduc · Projet Boréal · Hier, 16 h 20</p><button class="text-link" data-action="document" data-id="f3">Ouvrir le document ${icon('arrow')}</button></div></div><div class="notification-item">${icon('refresh')}<div><h3>Un profil acheteur à actualiser</h3><p>Groupe Horizon Est · Dernière vérification en août</p><button class="text-link" data-action="buyer" data-id="b5">Voir le profil ${icon('arrow')}</button></div></div>`,btn('Fermer','close','','secondary'),'Notifications de démonstration')},
 profile:()=>openModal('Votre espace conseil',`<div class="flex mb">${avatar('AL')}<div><h3>Alexandre Lambert</h3><p style="margin:5px 0 0">Conseiller principal · La Firme CTE</p></div></div><dl class="definition-list"><dt>Rôle de démonstration</dt><dd>Conseiller principal</dd><dt>Langue</dt><dd>Français (Canada)</dd><dt>Territoire</dt><dd>Québec & Chaudière-Appalaches</dd><dt>Cabinet</dt><dd>La Firme CTE</dd></dl><div class="callout"><h3>Un environnement pour explorer.</h3><p>Aucun compte ni service distant n’est connecté. Les changements sont enregistrés dans ce navigateur.</p></div>`,btn('Paramètres','settings','','secondary','settings')+btn('Mon parcours','learningProfile','','primary','book')),
 settings:()=>openModal('Un espace à votre rythme',`<div class="switch-row"><div>Résumé de la journée<small>Préférence locale · aucun courriel envoyé</small></div><input type="checkbox" class="switch" aria-label="Résumé de la journée" data-setting="digest" ${state.settings.digest?'checked':''}></div><div class="switch-row"><div>Rappels des prochaines actions<small>Préférence locale pour la démonstration</small></div><input type="checkbox" class="switch" aria-label="Rappels" data-setting="reminders" ${state.settings.reminders?'checked':''}></div><div class="switch-row"><div>Langue de l’interface<small>Français canadien, selon les ressources du projet</small></div>${badge('FR-CA','gray')}</div><div class="callout mt"><h3>Votre démonstration reste locale.</h3><p>Entreprises, tâches, profils et scénarios modifiés sont conservés dans ce navigateur. Exportez-les ou repartez du jeu initial.</p></div><div class="flex mt">${btn('Exporter les données','exportState','','secondary','download')}${btn('Réinitialiser la démo','resetConfirm','','danger','refresh')}</div>`,btn('Terminé','close','','primary','check')),
 resetConfirm:()=>openModal('Revenir au point de départ ?',`<p>Les modifications de cette démonstration seront remplacées par le jeu de données initial : tâches, profils, scénarios, documents et progression.</p><div class="callout"><h3>Vos fichiers d’origine sont préservés.</h3><p>Seules les données locales de la démo Nexus seront réinitialisées.</p></div>`,btn('Conserver mes modifications','close','','secondary')+btn('Réinitialiser','reset','','danger','refresh')),
 reset:()=>{state=structuredClone(seeds);save();closeModal();navigate('day');toast('La démonstration a retrouvé son état initial.')},
 exportState:()=>download('nexus-demo-donnees.json',JSON.stringify({demo:true,exportedAt:new Date().toISOString(),...state},null,2),'application/json'),
 newCompany:()=>openModal('Une nouvelle relation',`<p>Ajoutez une entreprise fictive à votre registre local.</p><form id="company-form" class="form-grid">${field('Nom de l’entreprise','companyName','','text','required maxlength="80"')}${field('Contact principal','companyContact','','text','required maxlength="80"')}${selectField('Secteur','companySector',['Fabrication','Distribution','Transport','Services'])}${field('Ville','companyCity','Québec','text','required maxlength="60"')}${field('Chiffre d’affaires ($)','companyRevenue','2500000','number','min="0" step="1000" required')}${field('BAIIA déclaré ($)','companyEbitda','400000','number','min="0" step="1000" required')}<div class="field full"><label for="companyNote">Description</label><textarea id="companyNote" name="description" maxlength="400" placeholder="Quelques mots sur l’entreprise…"></textarea></div></form>`,formActions('company-form','Ajouter au registre')),
 newDeal:()=>openModal('Ouvrir un nouveau dossier',`<p>Choisissez une entreprise du registre et définissez sa première prochaine action.</p><form id="deal-form" class="stack">${selectField('Entreprise','dealCompany',state.companies.map(c=>[c.id,c.name]))}${field('Nom confidentiel du projet','dealName','','text','required maxlength="60" placeholder="Ex. Projet Érable"')}${field('Prochaine action','dealNext','','text','required maxlength="120" placeholder="Ex. Planifier l’audit de sortie"')}${field('Date cible','dealDue','2026-10-27','date','required')}<div class="data-note">Le nouveau dossier est créé à l’étape Préparation dans cette démo. Aucune signature ni engagement réel n’est généré.</div></form>`,formActions('deal-form','Créer le dossier')),
 newTask:()=>openModal('Une prochaine action, clairement définie',`<form id="task-form" class="stack">${field('Action','taskTitle','','text','required maxlength="150" placeholder="Que faut-il faire avancer ?"')}${selectField('Mandat','taskDeal',state.deals.map(d=>[d.id,d.project]))}${field('Heure prévue','taskTime','16:00','time','required')}</form>`,formActions('task-form','Ajouter la tâche')),
 nextAction:id=>{const d=deal(id);openModal('Préciser le prochain pas',`<form id="next-form" data-id="${d.id}" class="stack">${field('Action','nextTitle',d.next,'text','required maxlength="150"')}${field('Échéance','nextDue','2026-10-27','date','required')}</form>`,formActions('next-form'),d.project)},
 addNote:id=>openModal('Une note pour le dossier',`<form id="note-form" data-id="${id}" class="stack"><div class="field"><label for="note">Votre note</label><textarea id="note" name="note" required maxlength="1200" placeholder="Une décision, un échange, un élément à confirmer…"></textarea></div></form>`,formActions('note-form')),
 meeting:()=>openModal('Prendre le temps d’échanger',`<p>Cette rencontre sera ajoutée à l’agenda de démonstration. Aucune invitation externe ne sera envoyée.</p><form id="meeting-form" class="form-grid"><div class="field full"><label for="meetingTitle">Objet</label><input id="meetingTitle" name="title" required maxlength="120" placeholder="Ex. Rencontre de qualification"></div>${field('Date','meetingDate','2026-10-23','date','required')}${field('Heure','meetingTime','15:00','time','required')}${selectField('Durée','meetingDuration',['30 minutes','45 minutes','60 minutes'])}${selectField('Type','meetingType',['Visioconférence','Au cabinet','Chez le client'])}</form>`,formActions('meeting-form','Ajouter à l’agenda')),
 refusal:id=>openModal('Comprendre une réponse',`<p>La réponse concerne cette opportunité. Elle ne modifie pas automatiquement les critères généraux de l’acheteur.</p><form id="refusal-form" data-id="${id}" class="stack">${selectField('Motif','reason',['Taille insuffisante','Taille trop importante','Secteur non recherché','Géographie','Prix trop élevé','Dépendance au dirigeant','Concentration client','Échéancier','Financement','Structure'])}<div class="field"><label for="refusalNote">Commentaire déclaré</label><textarea id="refusalNote" name="note" maxlength="500" placeholder="Ce que l’acheteur a précisé…"></textarea></div></form>`,formActions('refusal-form','Consigner la réponse'),buyer(id).name),
 upload:()=>openModal('Ajouter une pièce au dossier',`<p>Choisissez un fichier pour simuler son ajout. Seuls son nom, son type et sa taille sont conservés dans le navigateur.</p><form id="upload-form" class="stack"><div class="field"><label for="documentFile">Fichier</label><input id="documentFile" name="file" type="file" required accept=".pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg"></div>${selectField('Dossier','documentFolder',folders.map((f,i)=>[i,f]),folder<0?1:folder)}</form>`,formActions('upload-form','Ajouter la pièce')),
 requestDocument:()=>openModal('Une demande précise, une réponse plus simple',`<p>Préparez une demande locale. Elle sera ajoutée à vos tâches, sans envoi au cédant.</p><form id="request-form" class="stack">${field('Pièce demandée','requestName','','text','required maxlength="120" placeholder="Ex. Bail commercial renouvelé"')}${selectField('Dossier','requestFolder',folders.map((f,i)=>[i,f]))}<div class="field"><label for="requestReason">Pourquoi cette pièce est utile</label><textarea id="requestReason" name="reason" required maxlength="400" placeholder="Une explication courte pour le cédant…"></textarea></div></form>`,formActions('request-form','Préparer la demande')),
 proposalTask:()=>{if(state.tasks.some(t=>t.id==='proposal-refresh')){toast('Cette tâche existe déjà dans votre journée.');return}state.tasks.unshift({id:'proposal-refresh',title:'Confirmer le financement de Groupe Horizon Est',sub:'Profil acheteur · Suggestion révisée',time:'16 h 30',buyer:'b5',done:false});log('Proposition de tâche approuvée');closeModal();navigate('day');toast('La proposition approuvée a été ajoutée à votre journée.')},
 exportCompanies:()=>download('nexus-registre-demo.csv',csv([['Entreprise','Secteur','Ville','Revenus CAD','BAIIA CAD','Contact','Permission (démo)'],...state.companies.map(c=>[c.name,c.sector,c.city,c.revenue,c.ebitda,c.contact,c.permission])]),'text/csv;charset=utf-8'),
 exportFinance:id=>{const f=finance(deal(id)),v=financialValues(f);download('nexus-scenario-'+deal(id).code+'.csv',csv([['Scénario de démonstration','CAD — aucune évaluation professionnelle'],['Projet',deal(id).project],['BAIIA déclaré',f.ebitda],['Rémunération',f.owner?45000:0],['Loyer',f.rent?18000:0],['BAIIA ajusté',v.normalized],['Multiple',f.multiple],['VE prudente',v.low],['VE centrale',v.base],['VE haute',v.high],['Dette',f.debt],['Encaisse',f.cash],['Capitaux propres indicatifs',v.equity]]),'text/csv;charset=utf-8')},
 exportShortlist:id=>download('nexus-selection-interne-demo.csv',csv([['Document de démonstration — usage interne'],['Acquéreur','Secteur','Financement documenté','Sélectionné'],...rankedBuyers(deal(id)).filter(b=>state.shortlist.includes(b.id)).map(b=>[b.name,b.sector,b.financed?'Oui (démo)':'À confirmer','Oui'])]),'text/csv;charset=utf-8'),
 exportTimeline:id=>download('nexus-echeancier-'+deal(id).code+'.txt','ÉCHÉANCIER DE DÉMONSTRATION — '+deal(id).project+'\n\n1 octobre 2026 — Mandat signé (exemple)\n8 octobre — Collecte et préparation\n20 octobre — Mise en marché\n6 novembre — Rencontres acquéreurs (cible)\n20 novembre — Fenêtre de LI (cible)\nDécembre — Diligence et financement (conditionnel)\nClôture — Date à confirmer\n\nCe calendrier fictif ne constitue pas un engagement.'),
 exportTeaser:id=>{const d=deal(id),c=company(d.company);download('nexus-sommaire-aveugle-'+d.code+'.txt','BROUILLON DE DÉMONSTRATION — RÉVISION REQUISE\n\nRéférence : '+d.code+'\nSecteur : '+c.sector+' spécialisée\nRégion : '+c.region+'\nRevenus : '+money(Math.floor(c.revenue/1000000)*1000000,true)+' – '+money((Math.floor(c.revenue/1000000)+1)*1000000,true)+'\nBAIIA : '+money(Math.floor(c.ebitda/100000)*100000,true)+' – '+money((Math.floor(c.ebitda/100000)+1)*100000,true)+'\n\nRelève entrepreneuriale avec continuité de l’équipe. Structure à discuter avec le conseiller.\n\nDonnées fictives. Revue de confidentialité requise avant tout partage réel.')},
 downloadDoc:id=>{const f=state.docs.find(x=>x.id===id);download('nexus-fiche-document-'+f.id+'.txt','FICHE DE DOCUMENT — DÉMONSTRATION\n\nNom : '+f.name+'\nType : '+f.ext+'\nDossier : '+folders[f.folder]+'\nÉtat : '+f.status+'\nAjouté par : '+f.author+'\n\nCette fiche ne contient pas le document original. Seules les métadonnées de démonstration sont exportées.')},
 exportReport:()=>download('nexus-rapport-demo.csv',csv([['Rapport illustratif Nexus — données fictives'],['Période',state.reportRange],['Mandats actifs',state.deals.length],['Acquéreurs vérifiés',state.buyers.filter(b=>b.verified).length],['BAIIA moyen des entreprises',Math.round(state.companies.reduce((s,c)=>s+c.ebitda,0)/state.companies.length)],['Honoraires encaissés (fiction)',state.reportRange==='Année'?386000:state.reportRange==='Mois'?42000:128000],['Temps de préparation (fiction)',9.4]]),'text/csv;charset=utf-8')
};
function searchResults(q){q=q.toLowerCase().trim();const results=[...state.companies.map(c=>({id:c.id,title:c.name,sub:c.sector+' · '+c.city,action:'company',initial:c.initial,color:c.color})),...state.buyers.map(b=>({id:b.id,title:b.name,sub:b.type,action:'buyer',initial:b.initial,color:b.color})),...state.deals.map(d=>({id:d.id,title:d.project,sub:d.code+' · '+d.stage,action:'deal',initial:d.code.slice(-2),color:''}))].filter(x=>(x.title+' '+x.sub).toLowerCase().includes(q)).slice(0,8);return results.length?results.map(r=>`<button class="search-result" data-action="${r.action}" data-id="${r.id}">${mark(r)}<span><strong>${esc(r.title)}</strong><small>${esc(r.sub)}</small></span>${icon('arrow')}</button>`).join(''):'<p class="muted">Aucun résultat. Essayez un autre nom ou un code CTE.</p>'}
function handleSubmit(e){const form=e.target;if(!form.id)return;const ids=['company-form','buyer-form','deal-form','task-form','next-form','note-form','meeting-form','stage-form','refusal-form','call-form','intake-form','upload-form','request-form','discovery-form'];if(!ids.includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form),get=k=>String(f.get(k)||'').trim();let message='Modifications enregistrées.';
 switch(form.id){
 case 'company-form':{const name=get('companyName');if(!name||!get('companyContact')||!get('companyCity')||![get('companyRevenue'),get('companyEbitda')].every(v=>v!==''&&Number.isFinite(Number(v))&&Number(v)>=0)){toast('Vérifiez les champs requis et les montants non négatifs.');return}if(state.companies.some(c=>c.name.toLowerCase()===name.toLowerCase())){toast('Cette entreprise existe déjà dans le registre.');return}state.companies.push({id:'c'+Date.now()+'-'+state.companies.length,name,initial:name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase(),sector:get('companySector'),city:get('companyCity'),region:'Québec',revenue:Number(get('companyRevenue')),ebitda:Number(get('companyEbitda')),employees:'À préciser',age:0,contact:get('companyContact'),role:'Prospect',status:'À qualifier',score:0,color:'',source:'Saisie manuelle · Démonstration locale',permission:'À vérifier',description:get('description')||'Nouvelle entreprise à qualifier.'});page='companies';companyFilter='Toutes';message='L’entreprise a été ajoutée au registre local.';break}
 case 'buyer-form':{const min=Number(get('buyerMin')),max=Number(get('buyerMax'));if(!get('buyerName')||!get('buyerContact')||![get('buyerMin'),get('buyerMax')].every(v=>v!==''&&Number.isFinite(Number(v))&&Number(v)>=0)||min>max){toast('Vérifiez le profil et une fourchette de BAIIA valide, du minimum au maximum.');return}let b=state.buyers.find(x=>x.id===form.dataset.id);const name=get('buyerName');const values={name,contact:get('buyerContact'),type:get('buyerType'),sector:get('buyerSector'),city:get('buyerCity'),min,max,equity:get('buyerEquity'),verified:f.has('buyerVerified'),financed:f.has('buyerFinanced'),date:'23 oct. 2026',thesis:get('buyerThesis')};if(b)Object.assign(b,values);else state.buyers.push({id:'b'+Date.now()+'-'+state.buyers.length,initial:name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase(),nda:false,color:'',score:0,...values});message='Le profil et ses critères sont enregistrés.';break}
 case 'deal-form':{const c=company(get('dealCompany'));const id='d'+Date.now()+'-'+state.deals.length;state.deals.push({id,code:'CTE-'+String(31+state.deals.length-8).padStart(3,'0'),project:get('dealName'),company:c.id,stage:'Préparation',value:c.ebitda*4.5,days:0,next:get('dealNext'),due:formatDate(get('dealDue')),progress:5,type:'Vendeur',owner:'AL',sub:c.sector});detailId=id;detailTab='overview';page='deal';message='Votre nouveau dossier est prêt.';break}
 case 'task-form':{const d=deal(get('taskDeal'));state.tasks.unshift({id:'t'+Date.now()+'-'+state.tasks.length,title:get('taskTitle'),sub:d.project+' · Action ajoutée',time:get('taskTime').replace(':',' h '),deal:d.id,done:false});message='La tâche est ajoutée à votre journée.';page='day';break}
 case 'next-form':{const d=deal(form.dataset.id);d.next=get('nextTitle');d.due=formatDate(get('nextDue'));log('Prochaine action : '+d.next,d.project);message='La prochaine action est mise à jour.';break}
 case 'note-form':{log(get('note'),deal(form.dataset.id).project);message='Votre note est conservée dans le dossier.';break}
 case 'meeting-form':{state.meetings.push({title:get('title'),date:formatDate(get('meetingDate')),time:get('meetingTime').replace(':',' h '),duration:get('meetingDuration'),type:get('meetingType')});page='day';message='La rencontre est ajoutée à l’agenda de démo.';break}
 case 'stage-form':{if(!stages.includes(get('stage'))||!get('reason')){toast('Choisissez une étape et précisez le motif.');return}const d=deal(form.dataset.id),old=d.stage;if(typeof validateStageTransition==='function'){const issues=validateStageTransition(d,get('stage'));if(issues.length){depthShowIssues('Progression à préparer',issues);return}}d.stage=get('stage');if(typeof depthAudit==='function')depthAudit(d,'Étape : '+old+' → '+d.stage+' · '+get('reason'));d.days=0;if(typeof depthAudit!=='function')log(old+' → '+d.stage+' · '+get('reason'),d.project);message='La progression est consignée dans le dossier.';break}
 case 'refusal-form':{const b=buyer(form.dataset.id);if(!b.responses)b.responses=[];b.responses.push({deal:detailId,reason:get('reason'),note:get('note'),date:'23 oct. 2026'});log(b.name+' · Réponse consignée : '+get('reason'),deal(detailId).project);message='Réponse enregistrée. Les critères généraux sont préservés.';break}
 case 'call-form':{const c=company(form.dataset.id);if(get('disposition')==='Ne plus contacter')c.permission='Ne plus contacter';log('Simulation d’appel · '+c.name+' · '+get('disposition')+' — '+get('notes'),c.name);message='Le compte rendu de simulation est enregistré.';break}
 case 'intake-form':{const c=company(form.dataset.id);c.intake={name:get('intakeName'),horizon:get('horizon'),involvement:get('involvement'),goals:get('goals')};log('Questionnaire cédant complété · '+c.name,c.name);message='Réponses enregistrées localement.';break}
 case 'upload-form':{const file=$('#documentFile').files[0];if(!file)return;const ext=file.name.split('.').pop().toLowerCase(),targetFolder=Number(get('documentFolder'));if(!['pdf','docx','xlsx','csv','txt','png','jpg','jpeg'].includes(ext)||!Number.isInteger(targetFolder)||targetFolder<0||targetFolder>=folders.length){toast('Choisissez un format accepté et un dossier valide.');return}state.docs.unshift({id:'f'+Date.now()+'-'+state.docs.length,name:file.name.replace(/\.[^.]+$/,''),ext:file.name.split('.').pop().toUpperCase(),size:file.size>1024*1024?(file.size/1024/1024).toFixed(1)+' Mo':Math.max(1,Math.round(file.size/1024))+' ko',folder:Number(get('documentFolder')),status:'À réviser',author:'Alexandre Lambert',date:'23 oct.',local:true,deal:detailId});folder=Number(get('documentFolder'));message='La fiche du document est ajoutée. Aucun contenu n’est téléversé.';break}
 case 'request-form':{state.tasks.unshift({id:'req'+Date.now(),title:'Demander : '+get('requestName'),sub:'Projet Boréal · '+get('reason'),time:'À planifier',deal:'d1',done:false});log('Demande de pièce préparée : '+get('requestName'));message='Demande préparée dans vos tâches. Aucun message envoyé.';break}
 case 'discovery-form':{const d=deal(get('deal'));detailId=d.id;$('#discovery-results').innerHTML=`<div class="card card-pad"><div class="card-heading"><h2>${rankedBuyers(d).length} profils comparés pour ${esc(d.project)}</h2>${badge('Calcul terminé')}</div>${rankedBuyers(d).slice(0,3).map(b=>`<div class="check-row"><div class="match-score" style="width:40px;height:40px;font-size:14px;border-width:3px">${b.matchScore}</div><span>${esc(b.name)}<small class="muted" style="display:block;font-size:10px;margin-top:4px">${esc(b.sector)} · ${esc(b.city)}</small></span><button class="text-link" data-action="matchDetails" data-id="${b.id}">Comprendre ${icon('arrow')}</button></div>`).join('')}<div class="mt">${btn('Ouvrir la sélection','matches',d.id,'primary','arrow')}</div></div>`;toast('Les profils du réseau de démo ont été comparés.');return}
 }
 save();closeModal();render();toast(message);
}
function formatDate(date){if(!date)return 'À planifier';const d=new Date(date+'T12:00:00');return d.toLocaleDateString('fr-CA',{day:'numeric',month:'short'})}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-nav]');if(!el){if(mobileOpen&&!e.target.closest('.sidebar')){mobileOpen=false;render()}return}if(el.dataset.nav){closeModal();navigate(el.dataset.nav);return}const fn=actions[el.dataset.action];if(fn)fn(el.dataset.id,el)});
document.addEventListener('submit',handleSubmit);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='global-search'){$('#global-results').innerHTML=searchResults(el.value)}if(el.id==='company-search'||el.id==='buyer-search'){const id=el.id,pos=el.selectionStart;searchTerm=el.value;render();const next=$('#'+id);next?.focus();next?.setSelectionRange(pos,pos)}if(el.dataset.finance){const key=el.dataset.finance,f={...finance(deal(detailId))};if(el.type==='checkbox')f[key]=el.checked;else {const n=Number(el.value);if(!el.value||!Number.isFinite(n)||n<0||(key==='multiple'&&(n<1||n>20)))return;f[key]=n}if(!validFinancialInputs(f))return;state.financials[detailId]=f;save();$('#finance-results').innerHTML=financeResults(f);$('#equity-bridge').innerHTML=equityBridge(f)}});
document.addEventListener('change',e=>{if(e.target.dataset.setting){state.settings[e.target.dataset.setting]=e.target.checked;save();toast('Préférence enregistrée dans ce navigateur.')}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();actions.search()}if(e.key==='Escape'&&mobileOpen){mobileOpen=false;render()}if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('graph-node')){e.preventDefault();actions[e.target.dataset.action]?.(e.target.dataset.id)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
if(navs.some(n=>n[0]===location.hash.slice(1)))page=location.hash.slice(1);
render();
